const ts = require('/home/zhihao/deveco/command-line-tools/codelinter/linter/arkPerfCheck/node_modules/typescript');
const fs = require('fs');
const files = [
  'common/src/main/ets/default/view/ImageGridItemComponent.ets',
  'common/src/main/ets/default/view/browserOperation/MediaOperationBasePage.ets',
  'feature/timeline/src/main/ets/view/TimelinePage.ets'
];
let failed = false;
for (const file of files) {
  const source = fs.readFileSync(file, 'utf8');
  const tree = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const diagnostics = tree.parseDiagnostics || [];
  if (diagnostics.length) {
    failed = true;
    console.log(file);
    for (const d of diagnostics) console.log(ts.flattenDiagnosticMessageText(d.messageText, '\\n'));
  } else {
    console.log("'`${file}: parse ok`);
  }
}
process.exitCode = failed ? 1 : 0;
NODE'
